// Meta posts statuses (sent/delivered/read/failed) and inbound messages here.
// We keep delivered/read/failed (fewer sheet writes) and detect STOP-style opt-outs.
const body = $input.first().json.body || {};
const out = [];
const iso = ts => new Date(Number(ts) * 1000).toISOString();
for (const entry of (body.entry || [])) {
  for (const ch of (entry.changes || [])) {
    const v = ch.value || {};
    for (const s of (v.statuses || [])) {
      if (!['delivered', 'read', 'failed'].includes(s.status)) continue;
      const err = (s.errors && s.errors[0]) || {};
      out.push({ json: {
        campaign_id: s.biz_opaque_callback_data || '',
        wa_message_id: s.id,
        phone: s.recipient_id,
        status: s.status,
        error_code: err.code || '',
        error_text: (err.error_data && err.error_data.details) || err.message || err.title || '',
        timestamp: iso(s.timestamp)
      }});
    }
    for (const m of (v.messages || [])) {
      const txt = ((m.text && m.text.body) || (m.button && (m.button.text || m.button.payload)) ||
                   (m.interactive && m.interactive.button_reply && m.interactive.button_reply.title) || '')
                  .trim().toUpperCase();
      if (['STOP', 'UNSUBSCRIBE', 'STOP PROMOTIONS', 'OPT OUT', 'OPTOUT'].includes(txt)) {
        out.push({ json: {
          campaign_id: '', wa_message_id: m.id, phone: m.from, status: 'optout',
          error_code: '', error_text: '', timestamp: iso(m.timestamp)
        }});
      }
    }
  }
}
return out;
